def svg(name: str, size: int = 16, stroke: str = "currentColor", width: float = 2.0) -> str:
    body = _P.get(name, _P["box"])
    return (f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" '
            f'fill="none" stroke="{stroke}" stroke-width="{width}" stroke-linecap="round" '
            f'stroke-linejoin="round" style="flex-shrink:0;vertical-align:-2px">{body}</svg>')


def has(name: str) -> bool:
    return name in _P


